CREATE TABLE "sv_run_permits" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "dispatch_key" text NOT NULL, "channel" text NOT NULL, "scenario_id" text NOT NULL, "status" text DEFAULT 'issued' NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "sv_run_permits_dispatch_key_unique" ON "sv_run_permits" ("dispatch_key"); CREATE INDEX "sv_run_permits_org_cycle_idx" ON "sv_run_permits" ("organization_id", "cycle_id"); ALTER TABLE "sv_run_permits" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "sv_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "permit_id" uuid NOT NULL REFERENCES "sv_run_permits"("id"), "dispatch_key" text NOT NULL, "channel" text NOT NULL, "scenario_id" text NOT NULL, "status" text DEFAULT 'queued' NOT NULL, "raw_response_reference" text, "canonical_payload" jsonb, "started_at" timestamptz, "finished_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "sv_runs_dispatch_key_unique" ON "sv_runs" ("dispatch_key"); CREATE INDEX "sv_runs_org_cycle_idx" ON "sv_runs" ("organization_id", "cycle_id"); ALTER TABLE "sv_runs" ENABLE ROW LEVEL SECURITY;
